1	package meter
2	
3	import (
4		"sort"
5		"sync"
6		"time"
7	)
8	
9	// Service 是订阅、用量与账单的本地内存服务。
10	// 单个 *Service 可被多个 goroutine 并发使用：重复提交只会生效一次。
11	type Service struct {
12		mu       sync.Mutex
13		now      func() time.Time
14		accounts map[string]*account
15		plans    map[string]Plan
16	}
17	
18	type subRecord struct {
19		activatedAt time.Time
20		// terms 是本订阅段套餐条件的唯一事实来源，按生效月份升序保存，
21		// 首条为开通当月适用的开通快照，之后每条对应一次已生效的换套餐。
22		// 当前套餐标识、当前完整条件与任意历史账期的条件都统一由
23		// termsForPeriod 从中取出，开通与换套餐生效时只需在这里追加一份快照。
24		terms []termsEntry
25		// pending 尚未生效的换套餐安排，每账户至多一条；nil 表示无安排。
26		pending *PlanChange
27		// cancelEnd 已安排的终止时刻（取消请求时刻的下一个 UTC 自然月月初）。
28		// 非 nil 且尚未到达时为等待取消状态；到达后本订阅段终止并移入 history。
29		cancelEnd *time.Time
30		// endedAt 已终止订阅段的实际终止时刻；当前有效段为 nil。
31		endedAt *time.Time
32	}
33	
34	type eventRecord struct {
35		at     time.Time
36		qty    int64
37		period Month
38	}
39	
40	type billRecord struct {
41		bill Bill
42	}
43	
44	type paymentRecord struct {
45		period Month
46		amount int64
47		// balance 与 settled 是本笔付款首次成功登记完成时账单的余额与付清状态。
48		// 完全相同的重报原样返回该历史结果，不随后续付款或账单当前状态变化。
49		balance int64
50		settled bool
51	}
52	
53	type account struct {
54		id       string
55		sub      *subRecord
56		history  []*subRecord
57		events   map[string]eventRecord
58		usage    map[Month]int64
59		bills    map[Month]*billRecord
60		payments map[string]paymentRecord
61	}
62	
63	// NewService 创建一个以系统时钟判断“当前时刻”的服务。
64	func NewService() *Service {
65		return NewServiceWithClock(time.Now)
66	}
67	
68	// NewServiceWithClock 创建使用自定义时钟的服务，便于测试账期与截止时刻。
69	func NewServiceWithClock(now func() time.Time) *Service {
70		if now == nil {
71			now = time.Now
72		}
73		return &Service{
74			now:      now,
75			accounts: make(map[string]*account),
76			plans:    make(map[string]Plan),
77		}
78	}
79	
80	func (s *Service) nowUTC() time.Time {
81		return s.now().UTC()
82	}
83	
84	// CreateAccount 创建业务账户。账户标识必须非空且唯一。
85	func (s *Service) CreateAccount(id string) error {
86		if id == "" {
87			return invalidf("account id is empty")
88		}
89		s.mu.Lock()
90		defer s.mu.Unlock()
91		if _, ok := s.accounts[id]; ok {
92			return ErrAccountExists
93		}
94		s.accounts[id] = &account{
95			id:       id,
96			events:   make(map[string]eventRecord),
97			usage:    make(map[Month]int64),
98			bills:    make(map[Month]*billRecord),
99			payments: make(map[string]paymentRecord),
100		}
101		return nil
102	}
103	
104	func validatePlan(p Plan) error {
105		if p.ID == "" {
106			return invalidf("plan id is empty")
107		}
108		if p.MonthlyFee < 0 || p.IncludedUnits < 0 || p.OveragePrice < 0 {
109			return invalidf("plan %q has negative amount or quantity", p.ID)
110		}
111		if p.TaxRateBasisPoints < 0 || p.TaxRateBasisPoints > 10000 {
112			return invalidf("plan %q tax rate %d out of [0,10000]", p.ID, p.TaxRateBasisPoints)
113		}
114		return nil
115	}
116	
117	// CreatePlan 创建套餐。金额单位为分，税率为万分比且在 [0,10000]。
118	func (s *Service) CreatePlan(p Plan) error {
119		if err := validatePlan(p); err != nil {
120			return err
121		}
122		s.mu.Lock()
123		defer s.mu.Unlock()
124		if _, ok := s.plans[p.ID]; ok {
125			return ErrPlanExists
126		}
127		s.plans[p.ID] = p
128		return nil
129	}
130	
131	// UpdatePlan 更新套餐当前条件。只影响之后新保存的条件快照：之后开通的
132	// 订阅与之后新接受的换套餐安排按修改后的定义取得条件。已开通订阅继续
133	// 使用开通时保存的快照，已接受的换套餐安排继续使用安排时锁定的快照，
134	// 均不被改写。
135	func (s *Service) UpdatePlan(p Plan) error {
136		if err := validatePlan(p); err != nil {
137			return err
138		}
139		s.mu.Lock()
140		defer s.mu.Unlock()
141		if _, ok := s.plans[p.ID]; !ok {
142			return ErrPlanNotFound
143		}
144		s.plans[p.ID] = p
145		return nil
146	}
147	
148	// Subscribe 为账户开通订阅，并保存当时的套餐条件快照。
149	// 每个账户只允许一份有效订阅；从 activatedAt 起接收用量，
150	// 首月仍收完整月费并提供完整额度。
151	//
152	// activatedAt 可以晚于当前时刻，即提前登记一份尚未生效的订阅：登记会被保留，
153	// 但在实际开通时刻到达前 Status 的 Subscribed 为 false、CurrentTerms 为零值，
154	// 也没有待换套餐安排与待取消终止时刻；此期间再次开通仍返回
155	// ErrSubscriptionExists，安排换套餐、登记取消返回 ErrSubscriptionNotActivated。
156	// 判断以实际开通时刻为界（按同一瞬间比较，带时区的开通时间结果一致），不按
157	// 开通月份提前生效；到达开通时刻后查询即显示有效订阅与登记时保存的完整套餐
158	// 条件快照，等待期间修改套餐定义不改变该快照。
159	//
160	// 订阅终止（按月取消到达终止时刻）后可用本入口重新开通：activatedAt 不得早于
161	// 上一段订阅的终止时刻；重新开通保存当时的套餐条件，当月仍收完整月费、给完整
162	// 额度。重新开通不重置账户内事件与付款标识，也不清除旧欠费。同样允许登记未来
163	// 的重新开通时刻：旧订阅已结束、新订阅尚未开始的间隔中查询不显示任何生效套餐，
164	// 历史用量与账单继续可查。
165	func (s *Service) Subscribe(accountID, planID string, activatedAt time.Time) error {
166		if accountID == "" {
167			return invalidf("account id is empty")
168		}
169		if planID == "" {
170			return invalidf("plan id is empty")
171		}
172		if activatedAt.IsZero() {
173			return invalidf("activated at is zero")
174		}
175		s.mu.Lock()
176		defer s.mu.Unlock()
177		acc, ok := s.accounts[accountID]
178		if !ok {
179			return ErrAccountNotFound
180		}
181		now := s.nowUTC()
182		// 与其他入口保持一致：先让已到期的换套餐/取消落入历史。
183		s.settleLocked(acc, now)
184		plan, ok := s.plans[planID]
185		if !ok {
186			return ErrPlanNotFound
187		}
188		if acc.sub != nil {
189			return ErrSubscriptionExists
190		}
191		activated := activatedAt.UTC()
192		// 重新开通时刻不得早于上一段订阅的终止时刻。
193		if n := len(acc.history); n > 0 {
194			if activated.Before(*acc.history[n-1].endedAt) {
195				return ErrResubscribeBeforeEnd
196			}
197		}
198		acc.sub = &subRecord{
199			activatedAt: activated,
200			// 开通快照即条件时间线首条：当前条件与历史出账都从这里取。
201			terms: []termsEntry{{
202				effective: MonthOf(activated),
203				terms:     termsOf(plan),
204			}},
205		}
206		return nil
207	}
208	
209	// nextMonth 返回 period 的下一个 UTC 自然月。
210	func nextMonth(period Month) Month {
211		return MonthOf(period.End())
212	}
213	
214	// settleLocked 让当前订阅段中已到生效时刻的换套餐安排落入条件历史，
215	// 并在到达取消终止时刻时把当前段标记终止、移入 acc.history。
216	// 到达月初零点（或终止时刻）即生效，无需先上报用量或生成账单；即使中间若干月
217	// 没有调用服务，再次进入时也会在此一次性补齐。调用时持有 s.mu。
218	//
219	// 开通时刻尚未到达的订阅段只是提前登记：它尚未生效，既没有已生效的套餐条件，
220	// 也不可能有待换套餐安排或待取消终止时刻，因此在到达开通时刻前不做任何处理，
221	// 尤其不能按开通月份让条件“提前生效”。
222	func (s *Service) settleLocked(acc *account, now time.Time) {
223		sub := acc.sub
224		if sub == nil || now.Before(sub.activatedAt) {
225			return
226		}
227		current := MonthOf(now)
228		for sub.pending != nil && !current.Before(sub.pending.EffectivePeriod) {
229			// 换套餐生效只需向条件时间线追加一份锁定快照；
230			// 当前套餐标识与当前条件都由该时间线统一导出，无需另行更新。
231			sub.terms = append(sub.terms, termsEntry{
232				effective: sub.pending.EffectivePeriod,
233				terms:     sub.pending.Terms,
234			})
235			sub.pending = nil
236		}
237		if sub.cancelEnd != nil && !now.Before(*sub.cancelEnd) {
238			end := *sub.cancelEnd
239			sub.cancelEnd = nil
240			sub.pending = nil
241			sub.endedAt = &end
242			acc.history = append(acc.history, sub)
243			acc.sub = nil
244		}
245	}
246	
247	// coversInstant 报告订阅段是否覆盖时刻 at：半开区间 [activatedAt, end)，
248	// 开通时刻计入、终止时刻不计入。尚未生效的当前段（提前登记、开通时刻未到）
249	// 不覆盖任何时刻。订阅段的有效上界统一由 segmentEnd 给出：当前段已安排取消
250	// 时为登记的终止时刻（未到也一样，等待取消期间的事件必须落在终止之前），
251	// 已终止段为实际终止时刻，其余为无限远。所有时刻按同一瞬间比较，时区表达
252	// 不影响结果。
253	func coversInstant(sub *subRecord, at time.Time) bool {
254		if at.Before(sub.activatedAt) {
255			return false
256		}
257		if end, ended := segmentEnd(sub); ended && !at.Before(end) {
258			return false
259		}
260		return true
261	}
262	
263	// segmentEnd 返回订阅段的终止时刻（不含）：当前段已登记取消时是等待中的
264	// 终止时刻，已终止段是实际终止时刻；没有上界时 ended 为 false。
265	func segmentEnd(sub *subRecord) (time.Time, bool) {
266		if sub.endedAt != nil {
267			return *sub.endedAt, true
268		}
269		if sub.cancelEnd != nil {
270			return *sub.cancelEnd, true
271		}
272		return time.Time{}, false
273	}
274	
275	// coversMonth 报告订阅段是否让整个账期 period 成为可出账月份：
276	// 开通所在月计入（月中开通也按完整月出账），终止所在月不计入该段。
277	// 它是整月覆盖判断，不能由“月初那一刻是否被覆盖”代替——月中开通的月份
278	// 月初并不在订阅期间内，但整月仍归该订阅段出账。
279	func coversMonth(sub *subRecord, period Month) bool {
280		if period.Before(MonthOf(sub.activatedAt)) {
281			return false
282		}
283		if end, ended := segmentEnd(sub); ended && !period.Before(MonthOf(end)) {
284			return false
285		}
286		return true
287	}
288	
289	// termsForPeriod 在订阅段 sub 中返回指定账期当时适用的套餐条件快照。
290	// 条件时间线按生效月份升序，取不晚于 period 的最后一条；当前条件、
291	// 是否与当前套餐相同、历史账单出账全部经过这里，因此同一账期永远得到
292	// 同一份完整条件（月费、额度、超额单价、税率同源），不受之后的换套餐
293	// 或套餐定义修改影响。调用方须保证 sub.terms 非空（订阅段创建时即有首条）。
294	func termsForPeriod(sub *subRecord, period Month) PlanTerms {
295		t := sub.terms[0].terms
296		for _, e := range sub.terms {
297			if period.Before(e.effective) {
298				break
299			}
300			t = e.terms
301		}
302		return t
303	}
304	
305	// segmentsLocked 按订阅发生的先后返回账户的全部订阅段（已终止的历史段，
306	// 以及当前段）。订阅归属的唯一事实来源就是这些订阅段：每段的开通时刻与
307	// 终止时刻由 settleLocked 维护，时刻与整月两种覆盖判断都只经 coversInstant
308	// 与 coversMonth 访问它们，用量接收与账单出账因此对同一账户的订阅期间和
309	// 空档保持一致的依据。调用时持有 s.mu。
310	func segmentsLocked(acc *account) []*subRecord {
311		segs := make([]*subRecord, 0, len(acc.history)+1)
312		segs = append(segs, acc.history...)
313		if acc.sub != nil {
314			segs = append(segs, acc.sub)
315		}
316		return segs
317	}
318	
319	// segmentCoveringInstantLocked 返回覆盖时刻 at 的订阅段（coversInstant，
320	// 开通计入、终止不计入），没有任何段覆盖（空档、开通前、未来登记生效前）
321	// 时返回 nil。倒序检查使仍在延续的当前段优先命中。调用时持有 s.mu。
322	func segmentCoveringInstantLocked(acc *account, at time.Time) *subRecord {
323		segs := segmentsLocked(acc)
324		for i := len(segs) - 1; i >= 0; i-- {
325			if coversInstant(segs[i], at) {
326				return segs[i]
327			}
328		}
329		return nil
330	}
331	
332	// segmentCoveringMonthLocked 返回整月账期 period 出账应使用的订阅段
333	// （coversMonth：开通当月计入、终止当月不计入）。整月无任何段覆盖（早于
334	// 首段开通月，或处于两段之间的空档月）时返回 nil；月中重新开通的月份由
335	// 新订阅段覆盖，不沿用旧段条件。倒序检查使后来的段优先。调用时持有 s.mu。
336	func segmentCoveringMonthLocked(acc *account, period Month) *subRecord {
337		segs := segmentsLocked(acc)
338		for i := len(segs) - 1; i >= 0; i-- {
339			if coversMonth(segs[i], period) {
340				return segs[i]
341			}
342		}
343		return nil
344	}
345	
346	// SchedulePlanChange 安排账户从下一个 UTC 自然月起改用另一套餐，升级与降级规则相同。
347	//
348	// 成功时返回目标套餐在本次安排时的完整计费条件快照与生效账期（请求被接受时的
349	// 下一个 UTC 自然月），之后修改套餐定义不影响本安排。当前月仍按旧套餐收取完整
350	// 月费并提供完整额度，不按天补差，也不迁移本月已发生的用量。
351	//
352	// 每个账户至多保留一条尚未生效的安排：再次安排同一目标套餐时返回原安排，
353	// 不重新取价（Created 为 false）；安排另一目标套餐则替换原安排，生效月份仍为
354	// 本次请求被接受时的下一月。欠费停用期间也可以安排。
355	//
356	// 账户不存在、尚未开通订阅、开通时刻尚未到达、目标套餐不存在、目标套餐与当前
357	// 生效套餐相同时请求失败，原有安排保持不变。登记取消订阅会清除尚未生效的安排，
358	// 等待取消期间安排换套餐失败（ErrPlanChangeWhileCancelling）。
359	func (s *Service) SchedulePlanChange(accountID, targetPlanID string) (PlanChangeResult, error) {
360		if accountID == "" {
361			return PlanChangeResult{}, invalidf("account id is empty")
362		}
363		if targetPlanID == "" {
364			return PlanChangeResult{}, invalidf("target plan id is empty")
365		}
366		s.mu.Lock()
367		defer s.mu.Unlock()
368	
369		acc, ok := s.accounts[accountID]
370		if !ok {
371			return PlanChangeResult{}, ErrAccountNotFound
372		}
373		now := s.nowUTC()
374		// 先让已到期的安排/取消生效：例如跨月后的首次调用，此时“当前套餐”已是新套餐；
375		// 恰在换套餐生效的月初登记取消，先承认该次切换，取消从再下一月生效。
376		s.settleLocked(acc, now)
377		if acc.sub == nil {
378			return PlanChangeResult{}, ErrSubscriptionNotFound
379		}
380		if now.Before(acc.sub.activatedAt) {
381			return PlanChangeResult{}, ErrSubscriptionNotActivated
382		}
383		if acc.sub.cancelEnd != nil {
384			return PlanChangeResult{}, ErrPlanChangeWhileCancelling
385		}
386	
387		plan, ok := s.plans[targetPlanID]
388		if !ok {
389			return PlanChangeResult{}, ErrPlanNotFound
390		}
391		// 与当前生效套餐的比较同样取当前账期适用的完整条件，
392		// 保证“当前套餐”的判断与状态查询、出账同源。
393		if targetPlanID == termsForPeriod(acc.sub, MonthOf(now)).PlanID {
394			return PlanChangeResult{}, ErrPlanChangeSamePlan
395		}
396	
397		// 已有安排且目标相同：原样返回，不重新取价。
398		if acc.sub.pending != nil && acc.sub.pending.TargetPlanID == targetPlanID {
399			return PlanChangeResult{Created: false, Change: *acc.sub.pending}, nil
400		}
401	
402		change := PlanChange{
403			TargetPlanID:    targetPlanID,
404			Terms:           termsOf(plan),
405			EffectivePeriod: nextMonth(MonthOf(now)),
406		}
407		acc.sub.pending = &change
408		return PlanChangeResult{Created: true, Change: change}, nil
409	}
410	
411	// CancelPlanChange 在安排生效前取消它，取消后账户继续沿用当前套餐。
412	// 没有待生效安排时取消也成功；已生效的切换不会被撤回。
413	// 欠费停用期间也可以取消，取消不清除欠费、不解除停用。
414	// 账户不存在、订阅已终止（含已到终止时刻）时失败。
415	func (s *Service) CancelPlanChange(accountID string) error {
416		if accountID == "" {
417			return invalidf("account id is empty")
418		}
419		s.mu.Lock()
420		defer s.mu.Unlock()
421		acc, ok := s.accounts[accountID]
422		if !ok {
423			return ErrAccountNotFound
424		}
425		// 已到生效月份月初零点的安排视为已生效，不可撤回；已终止订阅段无当前订阅。
426		s.settleLocked(acc, s.nowUTC())
427		if acc.sub == nil {
428			return ErrSubscriptionNotFound
429		}
430		acc.sub.pending = nil
431		return nil
432	}
433	
434	// CancelSubscription 为当前有效订阅登记按月取消。
435	//
436	// 仅当订阅已生效（当前时刻不早于开通时刻）时可取消；欠费停用不妨碍取消，也不
437	// 免除债务。终止时刻为请求时刻的下一个 UTC 自然月月初零点（UTC）：当月照常
438	// 接收用量并按完整月费与额度计费，不按天退款。重复取消始终返回原终止时刻，
439	// 不把期限后移（Cancelled 为 false）。
440	//
441	// 成功时清除尚未生效的换套餐安排；若请求恰在某次换套餐生效的月初，先承认该次
442	// 切换，取消从再下一月生效。等待取消期间拒绝新的换套餐安排。
443	//
444	// 账户不存在、从未开通或当前无有效订阅、开通时刻尚未到达时请求失败。
445	func (s *Service) CancelSubscription(accountID string) (CancelSubscriptionResult, error) {
446		if accountID == "" {
447			return CancelSubscriptionResult{}, invalidf("account id is empty")
448		}
449		s.mu.Lock()
450		defer s.mu.Unlock()
451	
452		acc, ok := s.accounts[accountID]
453		if !ok {
454			return CancelSubscriptionResult{}, ErrAccountNotFound
455		}
456		now := s.nowUTC()
457		// 先补齐到期状态：恰在月初时先承认到期换套餐，终止时刻取再下一月。
458		s.settleLocked(acc, now)
459		if acc.sub == nil {
460			return CancelSubscriptionResult{}, ErrSubscriptionNotFound
461		}
462		if now.Before(acc.sub.activatedAt) {
463			return CancelSubscriptionResult{}, ErrSubscriptionNotActivated
464		}
465	
466		// 重复取消：原样返回原终止时刻，不后移期限。
467		if acc.sub.cancelEnd != nil {
468			return CancelSubscriptionResult{
469				Cancelled:    false,
470				Cancellation: SubscriptionCancellation{EndAt: *acc.sub.cancelEnd},
471			}, nil
472		}
473	
474		// 登记取消清除尚未生效的换套餐安排（撤回取消也不恢复它）。
475		acc.sub.pending = nil
476		end := nextMonth(MonthOf(now)).Start()
477		acc.sub.cancelEnd = &end
478		return CancelSubscriptionResult{
479			Cancelled:    true,
480			Cancellation: SubscriptionCancellation{EndAt: end},
481		}, nil
482	}
483	
484	// UndoCancelSubscription 在取消生效前撤回按月取消安排，撤回后订阅继续有效。
485	// 有效订阅没有取消安排时撤回也成功；撤回不恢复登记取消时被清除的换套餐安排。
486	// 终止时刻已到（订阅已终止）后撤回失败（ErrSubscriptionNotFound）；
487	// 账户不存在或从未开通时同样失败。
488	func (s *Service) UndoCancelSubscription(accountID string) error {
489		if accountID == "" {
490			return invalidf("account id is empty")
491		}
492		s.mu.Lock()
493		defer s.mu.Unlock()
494		acc, ok := s.accounts[accountID]
495		if !ok {
496			return ErrAccountNotFound
497		}
498		// 到达终止时刻后订阅已终止：撤回失败。
499		s.settleLocked(acc, s.nowUTC())
500		if acc.sub == nil {
501			return ErrSubscriptionNotFound
502		}
503		acc.sub.cancelEnd = nil
504		return nil
505	}
506	
507	// RecordEvent 上报一条用量事件。
508	//
509	// 事件按发生时刻归入 UTC 自然月账期；事件发生时刻必须属于某段实际订阅期间
510	// （开通时刻计入、终止时刻不计入），空档期间与晚于当前时刻的事件被拒绝。
511	// 订阅终止后仍可补报旧订阅期间且尚未出账的用量。
512	// 事件标识在同一账户内去重：完全相同的重报返回原结果且不重复累计——
513	// 即使发生在取消、重新开通之后也成功；相同标识但时刻或数量不同返回
514	// ErrEventConflict。
515	// 已出账月份拒绝新事件；账户因到期欠费停用时拒绝新增事件；
516	// 但此前已接收事件的完全相同重报始终成功。
517	func (s *Service) RecordEvent(e Event) (EventResult, error) {
518		if e.AccountID == "" {
519			return EventResult{}, invalidf("account id is empty")
520		}
521		if e.EventID == "" {
522			return EventResult{}, invalidf("event id is empty")
523		}
524		if e.Quantity < 0 {
525			return EventResult{}, invalidf("event %q has negative quantity %d", e.EventID, e.Quantity)
526		}
527		if e.At.IsZero() {
528			return EventResult{}, invalidf("event %q has zero timestamp", e.EventID)
529		}
530		at := e.At.UTC()
531	
532		s.mu.Lock()
533		defer s.mu.Unlock()
534	
535		acc, ok := s.accounts[e.AccountID]
536		if !ok {
537			return EventResult{}, ErrAccountNotFound
538		}
539	
540		now := s.nowUTC()
541		// 进入即补齐已到期的换套餐/取消，保证并发下各操作观察到一致的分段状态。
542		s.settleLocked(acc, now)
543	
544		// 从未开通订阅的账户没有任何订阅段。
545		if acc.sub == nil && len(acc.history) == 0 {
546			return EventResult{}, ErrSubscriptionNotFound
547		}
548	
549		// 去重优先：完全相同的重报即使发生在出账后、停用期间、取消或重新开通
550		// 之后也返回成功。
551		if prev, ok := acc.events[e.EventID]; ok {
552			if !prev.at.Equal(at) || prev.qty != e.Quantity {
553				return EventResult{}, ErrEventConflict
554			}
555			return EventResult{Accepted: false, Period: prev.period}, nil
556		}
557	
558		if at.After(now) {
559			return EventResult{}, ErrEventInFuture
560		}
561		// 事件发生时刻必须落在某段实际订阅期间：[activatedAt, end)。
562		// 与出账同源于 coversInstant/coversMonth，但这里按实际瞬间判定：
563		// 月中重新开通当月虽可整月出账，开通前的事件仍被拒绝。
564		if segmentCoveringInstantLocked(acc, at) == nil {
565			return EventResult{}, ErrEventBeforeSubscription
566		}
567	
568		period := MonthOf(at)
569		if _, billed := acc.bills[period]; billed {
570			return EventResult{}, ErrMonthBilled
571		}
572		if s.isSuspendedLocked(acc, now) {
573			return EventResult{}, ErrSuspended
574		}
575	
576		total, ok := addNonNeg(acc.usage[period], e.Quantity)
577		if !ok {
578			return EventResult{}, ErrOverflow
579		}
580		// 所有校验通过后才落库：失败不消耗事件标识。
581		acc.events[e.EventID] = eventRecord{at: at, qty: e.Quantity, period: period}
582		acc.usage[period] = total
583		return EventResult{Accepted: true, Period: period}, nil
584	}
585	
586	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
587	// 只能为某段订阅实际覆盖的、且已经结束的月份生成账单：开通当月计入、终止
588	// 当月（终止时刻所在月）不计入该段，完全无订阅的空档月份出账失败。
589	// 取消订阅不自动出账；终止后旧订阅覆盖的已结束月份仍可出账，使用各月当时
590	// 锁定的条件。重复调用得到同一账单；出账后金额与用量明细固定。
591	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
592		if accountID == "" {
593			return Bill{}, invalidf("account id is empty")
594		}
595		if period.Month < time.January || period.Month > time.December {
596			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
597		}
598		s.mu.Lock()
599		defer s.mu.Unlock()
600	
601		acc, ok := s.accounts[accountID]
602		if !ok {
603			return Bill{}, ErrAccountNotFound
604		}
605		if existing, ok := acc.bills[period]; ok {
606			return existing.bill, nil
607		}
608	
609		now := s.nowUTC()
610		// 补齐到期换套餐/取消（条件历史与分段），随后按账期取覆盖该月的订阅段中
611		// 当时适用的条件：即使已重新开通或先出新月份账单再补旧月份账单，历史账单
612		// 也不会被后来的订阅覆盖。
613		s.settleLocked(acc, now)
614	
615		if acc.sub == nil && len(acc.history) == 0 {
616			return Bill{}, ErrSubscriptionNotFound
617		}
618		if period.End().After(now) {
619			return Bill{}, ErrBillMonthNotEnded
620		}
621	
622		sub := segmentCoveringMonthLocked(acc, period)
623		if sub == nil {
624			// 早于首段开通，或处于两段订阅之间的空档。
625			return Bill{}, ErrBillBeforeSubscription
626		}
627	
628		terms := termsForPeriod(sub, period)
629		bill, err := buildBill(accountID, period, terms, acc.usage[period])
630		if err != nil {
631			return Bill{}, err
632		}
633		acc.bills[period] = &billRecord{bill: bill}
634		return bill, nil
635	}
636	
637	// GetBill 返回指定账期的账单；尚未出账返回 ErrBillNotFound。
638	func (s *Service) GetBill(accountID string, period Month) (Bill, error) {
639		if accountID == "" {
640			return Bill{}, invalidf("account id is empty")
641		}
642		s.mu.Lock()
643		defer s.mu.Unlock()
644		acc, ok := s.accounts[accountID]
645		if !ok {
646			return Bill{}, ErrAccountNotFound
647		}
648		rec, ok := acc.bills[period]
649		if !ok {
650			return Bill{}, ErrBillNotFound
651		}
652		return rec.bill, nil
653	}
654	
655	// RecordPayment 为指定账单登记一笔大于零且不超过余额的本地付款，支持分次登记。
656	// 付款标识在同一账户内去重：相同账单和金额的重报仍成功，但本次不再登记
657	// （Registered 为 false），也不再次增加已付金额；返回的付款内容、账单余额与
658	// 付清状态均为该笔付款首次成功登记完成时的历史结果，不随后续付款或账单当前
659	// 状态变化（例如账单后来已结清，重报早先的部分付款仍返回当时的未清余额与
660	// 未付清）。账单查询与账户状态中的余额始终反映当前状态，不受重报影响。
661	// 相同标识但账期或金额不同返回 ErrPaymentConflict：即使原账单已结清，或改指
662	// 向的账期还没有账单，也按冲突处理而非当作新付款。失败不消耗付款标识。
663	func (s *Service) RecordPayment(accountID, paymentID string, period Month, amount int64) (PaymentResult, error) {
664		if accountID == "" {
665			return PaymentResult{}, invalidf("account id is empty")
666		}
667		if paymentID == "" {
668			return PaymentResult{}, invalidf("payment id is empty")
669		}
670		if amount <= 0 {
671			return PaymentResult{}, invalidf("payment %q amount must be positive, got %d", paymentID, amount)
672		}
673		s.mu.Lock()
674		defer s.mu.Unlock()
675	
676		acc, ok := s.accounts[accountID]
677		if !ok {
678			return PaymentResult{}, ErrAccountNotFound
679		}
680		// 去重先于账单查找：相同标识改指向其他账单（哪怕不存在）也是冲突。
681		if prev, ok := acc.payments[paymentID]; ok {
682			if prev.period != period || prev.amount != amount {
683				return PaymentResult{}, ErrPaymentConflict
684			}
685			// 完全相同的重报仍成功，但不再次登记、不改变账单：
686			// 返回这笔付款首次成功登记完成时的余额与付清状态，
687			// 不受账单后续收款、当前余额或停用/恢复状态影响。
688			return PaymentResult{
689				Registered:  false,
690				Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
691				BillBalance: prev.balance,
692				Settled:     prev.settled,
693			}, nil
694		}
695	
696		rec, ok := acc.bills[period]
697		if !ok {
698			return PaymentResult{}, ErrBillNotFound
699		}
700	
701		if amount > rec.bill.Balance {
702			return PaymentResult{}, ErrPaymentExceedsBalance
703		}
704	
705		paid, ok := addNonNeg(rec.bill.Paid, amount)
706		if !ok {
707			return PaymentResult{}, ErrOverflow
708		}
709		rec.bill.Paid = paid
710		rec.bill.Balance -= amount
711		if rec.bill.Balance == 0 {
712			rec.bill.Settled = true
713		}
714		// 保存首次登记完成时的历史结果，供完全相同重报原样返回。
715		acc.payments[paymentID] = paymentRecord{
716			period:  period,
717			amount:  amount,
718			balance: rec.bill.Balance,
719			settled: rec.bill.Settled,
720		}
721	
722		return PaymentResult{
723			Registered:  true,
724			Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
725			BillBalance: rec.bill.Balance,
726			Settled:     rec.bill.Settled,
727		}, nil
728	}
729	
730	// MonthlyUsage 返回账户某账期的累计用量；无任何用量时返回 0。
731	func (s *Service) MonthlyUsage(accountID string, period Month) (Usage, error) {
732		if accountID == "" {
733			return Usage{}, invalidf("account id is empty")
734		}
735		s.mu.Lock()
736		defer s.mu.Unlock()
737		acc, ok := s.accounts[accountID]
738		if !ok {
739			return Usage{}, ErrAccountNotFound
740		}
741		// 与其他入口保持一致：顺带让已到期的换套餐/取消生效。
742		s.settleLocked(acc, s.nowUTC())
743		return Usage{Period: period, Total: acc.usage[period]}, nil
744	}
745	
746	// Status 返回账户状态：各月累计用量、各账单余额以及当前是否因欠费停用。
747	func (s *Service) Status(accountID string) (AccountStatus, error) {
748		if accountID == "" {
749			return AccountStatus{}, invalidf("account id is empty")
750		}
751		s.mu.Lock()
752		defer s.mu.Unlock()
753		acc, ok := s.accounts[accountID]
754		if !ok {
755			return AccountStatus{}, ErrAccountNotFound
756		}
757	
758		now := s.nowUTC()
759		// 查询即让已到期安排/取消生效：月初零点或终止时刻之后无需上报用量或出账，
760		// 当前条件与订阅状态立即更新。
761		s.settleLocked(acc, now)
762	
763		// 订阅是否生效以实际开通时刻为界：提前登记、开通时刻尚未到达的订阅仍
764		// 保存在 acc.sub 中（再次开通、安排换套餐、登记取消均按已有订阅的规则
765		// 处理），但查询时刻不显示为有效订阅。到达开通时刻即生效，不按开通月份
766		// 提前生效；时刻按同一瞬间比较，使用带时区的时间结果一致。
767		active := acc.sub != nil && !now.Before(acc.sub.activatedAt)
768	
769		periodSet := make(map[Month]struct{}, len(acc.usage)+len(acc.bills))
770		for m := range acc.usage {
771			periodSet[m] = struct{}{}
772		}
773		for m := range acc.bills {
774			periodSet[m] = struct{}{}
775		}
776		periods := make([]Month, 0, len(periodSet))
777		for m := range periodSet {
778			periods = append(periods, m)
779		}
780		sortMonths(periods)
781	
782		st := AccountStatus{
783			AccountID:    accountID,
784			Subscribed:   active,
785			Suspended:    s.isSuspendedLocked(acc, now),
786			MonthlyUsage: make([]Usage, 0, len(periods)),
787			Bills:        make([]BillSummary, 0, len(acc.bills)),
788		}
789		// 仅实际生效的订阅才展示当前套餐条件、待换套餐安排与已安排终止时刻；
790		// 等待开通期间这些字段均为零值（查询不删除也不提前激活已登记订阅）。
791		if active {
792			// 当前条件与历史出账取自同一份条件时间线：月初零点 settleLocked
793			// 追加新快照后，这里直接拿到安排时锁定的完整条件，无需另行同步。
794			st.CurrentTerms = termsForPeriod(acc.sub, MonthOf(now))
795			if acc.sub.pending != nil {
796				pending := *acc.sub.pending
797				st.PendingChange = &pending
798			}
799			if acc.sub.cancelEnd != nil {
800				end := *acc.sub.cancelEnd
801				st.ScheduledEnd = &end
802			}
803		}
804		for _, m := range periods {
805			st.MonthlyUsage = append(st.MonthlyUsage, Usage{Period: m, Total: acc.usage[m]})
806		}
807		for _, m := range periods {
808			if rec, ok := acc.bills[m]; ok {
809				b := rec.bill
810				st.Bills = append(st.Bills, BillSummary{
811					Period:   m,
812					TotalDue: b.TotalDue,
813					Paid:     b.Paid,
814					Balance:  b.Balance,
815					Settled:  b.Settled,
816					DueAt:    b.DueAt,
817				})
818			}
819		}
820		return st, nil
821	}
822	
823	// isSuspendedLocked 报告账户当前是否停用：
824	// 存在到达付款截止时刻仍有余额的账单。调用时持有 s.mu。
825	func (s *Service) isSuspendedLocked(acc *account, now time.Time) bool {
826		for _, rec := range acc.bills {
827			if !rec.bill.Settled && !now.Before(rec.bill.DueAt) {
828				return true
829			}
830		}
831		return false
832	}
833	
834	func sortMonths(ms []Month) {
835		sort.Slice(ms, func(i, j int) bool { return ms[i].Before(ms[j]) })
836	}
837	
838	// addNonNeg 返回两个非负 int64 之和；溢出时 ok=false。
839	func addNonNeg(a, b int64) (int64, bool) {
840		if a > maxInt64-b {
841			return 0, false
842		}
843		return a + b, true
844	}
845	
846	// mulNonNeg 返回两个非负 int64 之积；溢出时 ok=false。
847	func mulNonNeg(a, b int64) (int64, bool) {
848		if a == 0 || b == 0 {
849			return 0, true
850		}
851		if a > maxInt64/b {
852			return 0, false
853		}
854		return a * b, true
855	}
856	
857	// buildBill 依据套餐快照和账期总用量计算账单，所有金额运算做溢出检查。
858	func buildBill(accountID string, period Month, t PlanTerms, totalUsage int64) (Bill, error) {
859		overageUnits := int64(0)
860		if totalUsage > t.IncludedUnits {
861			overageUnits = totalUsage - t.IncludedUnits
862		}
863		overageFee, ok := mulNonNeg(overageUnits, t.OveragePrice)
864		if !ok {
865			return Bill{}, ErrOverflow
866		}
867		subtotal, ok := addNonNeg(t.MonthlyFee, overageFee)
868		if !ok {
869			return Bill{}, ErrOverflow
870		}
871		tax, ok := rateAmount(subtotal, t.TaxRateBasisPoints)
872		if !ok {
873			return Bill{}, ErrOverflow
874		}
875		totalDue, ok := addNonNeg(subtotal, tax)
876		if !ok {
877			return Bill{}, ErrOverflow
878		}
879		b := Bill{
880			AccountID:     accountID,
881			Period:        period,
882			Terms:         t,
883			TotalUsage:    totalUsage,
884			IncludedUnits: t.IncludedUnits,
885			OverageUnits:  overageUnits,
886			MonthlyFee:    t.MonthlyFee,
887			OverageFee:    overageFee,
888			Tax:           tax,
889			TotalDue:      totalDue,
890			Paid:          0,
891			Balance:       totalDue,
892			Settled:       totalDue == 0,
893			DueAt:         period.End().AddDate(0, 0, 7),
894		}
895		return b, nil
896	}
897	
898	// rateAmount 计算 amount*rate/10000 并四舍五入到分（非负数，半数向上）。
899	// 拆分商和余数计算以避免乘积溢出 int64。
900	func rateAmount(amount, rate int64) (int64, bool) {
901		const den = 10000
902		q, r := amount/den, amount%den
903		qr, ok := mulNonNeg(q, rate)
904		if !ok {
905			return 0, false
906		}
907		rr, ok := mulNonNeg(r, rate)
908		if !ok {
909			return 0, false
910		}
911		// 四舍五入：(rr + den/2) / den，rr < den*10001 < 1e8，加 den/2 不溢出。
912		add, ok := addNonNeg(qr, (rr+den/2)/den)
913		if !ok {
914			return 0, false
915		}
916		return add, true
917	}
918

