37	// activationDefs 汇总一次“开通与改价争用”涉及的三份定义：原定义、
38	// 同时提交的修改后定义、争用结束后的第三次定义（四项与前两份全不相同）。
39	type activationDefs struct {
40		planID                       string
41		oldDef, updatedDef, laterDef Plan
42	}
