53	// newActivationRaceService 在 2026-01-15 12:00 UTC（一月中旬）构造服务，
54	// 建好按原定义存在的套餐 d.planID 与一个尚无订阅、无账单无欠费的账户。
55	func newActivationRaceService(t *testing.T, acct string, d activationDefs) (*Service, *fakeClock) {
56		t.Helper()
57		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
58		mustPlan(t, s, d.oldDef)
59		mustAccount(t, s, acct)
