101		}
102		if got != oldTerms && got != updatedTerms {
103			t.Fatalf("%q saved mixed terms %+v, want whole old %+v or whole updated %+v",
104				acct, got, oldTerms, updatedTerms)
105		}
106		// 逐项再核一遍，使字段级混搭在失败信息中无处遁形：四个计费字段必须
107		// 同时来自同一份定义。
108		if got.MonthlyFee == oldTerms.MonthlyFee {
109			if got != oldTerms {
110				t.Fatalf("%q monthly fee from old but other fields not: %+v", acct, got)
111			}
112		} else {
113			if got != updatedTerms {
114				t.Fatalf("%q terms neither fully old nor fully updated: %+v", acct, got)
115			}
