131		if err != nil {
132			t.Fatalf("status %q after later update: %v", acct, err)
133		}
134		if !st.Subscribed || st.CurrentTerms != saved {
135			t.Fatalf("%q snapshot rewritten by later plan update: %+v, want %+v",
136				acct, st.CurrentTerms, saved)
137		}
