220		}
221		if u, _ := s.MonthlyUsage(acct, jan(2026)); u.Total != 25 {
222			t.Fatalf("%q jan usage after billing = %d, want 25", acct, u.Total)
223		}
224		st, _ = s.Status(acct)
225		if !st.Subscribed || st.CurrentTerms != saved {
226			t.Fatalf("%q current terms after billing = %+v, want %+v", acct, st.CurrentTerms, saved)
227		}
228	
229		// 出账后再改一次套餐定义：已固定的账单与账户快照都不被改写。
230		if err := s.UpdatePlan(planDef(d.planID, 4000, 40, 400, 900)); err != nil {
231			t.Fatalf("post-billing plan update: %v", err)
232		}
233		again, err := s.GetBill(acct, jan(2026))
234		if err != nil {
235			t.Fatalf("get bill after update %q: %v", acct, err)
236		}
237		if again != bill {
238			t.Fatalf("%q bill changed after later plan update:\nbefore=%+v\nafter =%+v", acct, bill, again)
239		}
