1	package meter
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	// 回归测试：待生效目标从乙换成丙、再改回乙时，最后一次选择乙是
9	// 新接受的安排，必须按当时的乙定义重新保存条件快照，不能复用最早
10	// 那次已被替换的乙安排，也不能混入中途丙的条件。这与连续选择同一
11	// 待生效目标的重报（返回原安排、不重新取价）不同。
12	func TestRescheduleBackToPreviousTargetTakesFreshTerms(t *testing.T) {
13		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
14		// 甲：月费 1000、包含 10、超额单价 100、无税。
15		mustPlan(t, s, planDef("a", 1000, 10, 100, 0))
16		// 乙首次定义：月费 2000、包含 20、超额单价 200、税率 10%。
17		mustPlan(t, s, planDef("b", 2000, 20, 200, 1000))
18		// 丙：月费 5000、包含 50、超额单价 500、税率 25%。
19		mustPlan(t, s, planDef("c", 5000, 50, 500, 2500))
20		mustAccount(t, s, "u")
21		// 账户无欠费，自 2026-01 起使用甲。
22		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
23	
24		// 一月用量 15 单位，发生在甲的有效订阅期间、账户未停用。
