14		mustPlan(t, s, planDef("b", 2000, 20, 200, 1000))
15		mustAccount(t, s, "u")
16		// 账户自 2026-01 起使用甲。
17		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
18	
19		// 一月中旬安排二月改用乙：锁定乙当时的条件。
20		r1 := mustSchedule(t, s, "u", "b")
21		firstChange := PlanChange{
22			TargetPlanID:    "b",
23			Terms:           termsOf(planDef("b", 2000, 20, 200, 1000)),
24			EffectivePeriod: feb(2026),
25		}
26		if !r1.Created || r1.Change != firstChange {
27			t.Fatalf("first schedule: %+v", r1)
28		}
