31		if err := s.UpdatePlan(planDef("b", 3000, 30, 300, 600)); err != nil {
32			t.Fatal(err)
33		}
34		st, _ := s.Status("u")
35		if st.PendingChange == nil || *st.PendingChange != firstChange {
36			t.Fatalf("pending rewritten by update: %+v", st.PendingChange)
37		}
38	
39		// 取消安排：无待生效安排，甲的完整条件不变。
40		if err := s.CancelPlanChange("u"); err != nil {
41			t.Fatalf("cancel: %v", err)
42		}
43		st, _ = s.Status("u")
44		if st.PendingChange != nil || st.CurrentTerms != termsOf(planDef("a", 1000, 10, 100, 0)) {
45			t.Fatalf("after cancel: cur=%+v pending=%+v", st.CurrentTerms, st.PendingChange)
46		}
47	
48		// 到达二月月初：不能自动切换到乙，仍是甲。
49		clk.t = utc(2026, 2, 1, 0, 0)
