52			t.Fatalf("feb after cancel: cur=%+v pending=%+v", st.CurrentTerms, st.PendingChange)
53		}
54	
55		// 二月用量 15 单位，发生在甲的有效订阅期间、账户未停用。
56		clk.t = utc(2026, 2, 15, 12, 0)
57		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "e-feb", At: utc(2026, 2, 10, 0, 0), Quantity: 15}); err != nil {
58			t.Fatal(err)
59		}
